// Weekly fleet KPIs from fault events. Events: {robot_id, start, end} downtime intervals plus {code}.
const WEEK_H = 7 * 24;
const events = $input.first().json.events || [];
const robots = $input.first().json.robots || [...new Set(events.map((e) => e.robot_id))];
const down = {};
const codes = {};
for (const e of events) {
  const h = Math.max(0, (Date.parse(e.end) - Date.parse(e.start)) / 36e5);
  down[e.robot_id] = (down[e.robot_id] || 0) + h;
  codes[e.code] = (codes[e.code] || 0) + 1;
}
const totalDown = Object.values(down).reduce((a, b) => a + b, 0);
const fleetHours = robots.length * WEEK_H;
const kpis = {
  robots: robots.length,
  failures: events.length,
  availability_pct: +(100 * (1 - totalDown / fleetHours)).toFixed(1),
  mtbf_h: events.length ? +((fleetHours - totalDown) / events.length).toFixed(1) : null,
  mttr_h: events.length ? +(totalDown / events.length).toFixed(1) : null,
  top_codes: Object.entries(codes).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([code, n]) => ({ code, n })),
  worst_robot: Object.entries(down).sort((a, b) => b[1] - a[1]).map(([id, h]) => ({ id, down_h: +h.toFixed(1) }))[0] || null,
};
const state = $getWorkflowStaticData('global');
const previous = state.lastWeek || null;
state.lastWeek = kpis;
return [{ json: { kpis, previous } }];

// ---- shared helpers (inlined by the builder; n8n Code nodes cannot import files) ----
function claudeRequest(system, user, { model = 'claude-haiku-4-5-20251001', maxTokens = 1024 } = {}) {
  // Body for POST https://api.anthropic.com/v1/messages
  return { model, max_tokens: maxTokens, system, messages: [{ role: 'user', content: user }] };
}

function claudeText(response) {
  // Concatenate the text blocks of a Messages API response.
  const blocks = (response && response.content) || [];
  return blocks.filter((b) => b.type === 'text').map((b) => b.text).join('');
}

function extractJson(text) {
  // Models sometimes wrap JSON in prose or code fences: take the outermost {...} or [...].
  if (typeof text !== 'string') return null;
  const starts = [text.indexOf('{'), text.indexOf('[')].filter((i) => i >= 0);
  if (!starts.length) return null;
  const start = Math.min(...starts);
  const end = Math.max(text.lastIndexOf('}'), text.lastIndexOf(']'));
  if (end <= start) return null;
  try { return JSON.parse(text.slice(start, end + 1)); } catch (e) { return null; }
}
// ---- end shared helpers ----

const { kpis, previous } = $input.first().json;
const system = 'You write a weekly operations summary for company leadership. Use ONLY the numbers provided; ' +
  'do not compute new ones. Five bullets maximum, plain language, end with one recommended action.';
const user = `This week: ${JSON.stringify(kpis)}\nLast week: ${JSON.stringify(previous)}`;
return [{ json: { body: claudeRequest(system, user, { maxTokens: 500 }) } }];

